function validate([target]) {
  if (!Array.isArray(target) || target.length < 1 || target.length > 50000) return 'target needs 1 to 50000 values.';
  if (target.some(v => !Number.isInteger(v) || v < 1 || v > 1e9)) return 'Each value is an integer from 1 to 10^9.';
