  // A max-heap of the current values.
  const heap = [];
  const push = value => {
    heap.push(value);
    let i = heap.length - 1;
    while (i > 0 && heap[(i - 1) >> 1] < heap[i]) {
      const parent = (i - 1) >> 1;
      [heap[parent], heap[i]] = [heap[i], heap[parent]];
      i = parent;
    }
  };
  const pop = () => {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length > 0) {
      heap[0] = last;
      let i = 0;
      for (;;) {
        let largest = i;
        for (const child of [2 * i + 1, 2 * i + 2]) {
          if (child < heap.length && heap[child] > heap[largest]) {
            largest = child;
          }
        }
        if (largest === i) {
          break;
        }
        [heap[i], heap[largest]] = [heap[largest], heap[i]];
        i = largest;
      }
    }
    return top;
  };

  let total = 0;
  for (const value of target) {
    total += value;
    push(value);
  }

  while (true) {
    const largest = pop();
    const rest = total - largest;
    if (largest === 1 || rest === 1) {
      return true;
    }
    if (rest === 0 || largest <= rest) {
      return false;
    }
    const previous = largest % rest;
    if (previous === 0) {
      return false;
    }
    push(previous);
    total = rest + previous;
  }
}

