function isPossible(target) {
  const n = target.length;
  let total = 0;
  for (const v of target) total += v;
  if (total <= 200) {
    // Small targets: search forward from all ones. Values never shrink, so a state above target anywhere is dead.
    const goal = target.join(',');
    const seen = new Set();
    const stack = [new Array(n).fill(1)];
    while (stack.length > 0) {
      const arr = stack.pop();
      const key = arr.join(',');
      if (key === goal) return true;
      if (seen.has(key)) continue;
      seen.add(key);
      let sum = 0;
      for (const v of arr) sum += v;
      for (let i = 0; i < n; i++) {
        if (sum <= target[i] && sum !== arr[i]) {
          const next = arr.slice();
          next[i] = sum;
          stack.push(next);
        }
      }
    }
    return false;
  }
  // Large targets: undo moves backward, scanning for the maximum each time and undoing every
  // consecutive move on that position in one jump (to the first value that is no longer above the others).
  const arr = target.slice();
  for (;;) {
    let m = 0;
    for (let i = 1; i < n; i++) if (arr[i] > arr[m]) m = i;
    if (arr[m] === 1) return true;
    const others = total - arr[m];
    if (others < 1 || arr[m] <= others) return false;
    const jumps = Math.ceil((arr[m] - others) / others);
    const earlier = arr[m] - jumps * others;
    if (earlier < 1) return false;
    total = total - arr[m] + earlier;
    arr[m] = earlier;
  }
}

