function generate(rand, size) {
  const large = size === 'large';
  const limit = large ? 1e9 : 40;
  const pick = k => Math.floor(rand() * k);
  const mode = rand();
  let n;
  if (large) n = mode < 0.3 ? 2 : 2 + pick(1999);
  else n = 1 + pick(4);
  let arr;
  if (mode < 0.75) {
    // Play random forward moves so the answer is often true.
    arr = new Array(n).fill(1);
    let sum = n;
    const steps = large ? 200 : pick(7);
    for (let s = 0; s < steps; s++) {
      const i = pick(n);
      if (sum > limit) break;
      const next = sum;
      sum += next - arr[i];
      arr[i] = next;
    }
    if (rand() < 0.4) {
      // Nudge one value to produce a near miss.
      const j = pick(n);
      arr[j] = Math.min(limit, Math.max(1, arr[j] + (rand() < 0.5 ? -1 : 1)));
    }
  } else {
    const top = large ? 1e9 : 12;
    arr = Array.from({ length: n }, () => 1 + pick(top));
  }
  return [arr];
}
